function design_p(string $s): string {return '<!-- wp:paragraph --><p>'.esc_html($s).'</p><!-- /wp:paragraph -->';}
function design_h(string $s): string {return '<!-- wp:heading --><h2 class="wp-block-heading">'.esc_html($s).'</h2><!-- /wp:heading -->';}
function design_sections(array $sections): string {$out='';foreach($sections as $heading=>$text)$out.=design_h($heading).design_p($text);return $out;}
